; [RFC8747] $$Claims-Set-Claims //= ( 8: CWT-cnf ) ; cnf CWT-cnf = { (1: CWT-COSE-Key) // (2: CWT-Encrypted_COSE_Key) // (3: CWT-kid) }
CWT-COSE-Key = COSE_Key CWT-Encrypted_COSE_Key = COSE_Encrypt / COSE_Encrypt0 CWT-kid = bytes
;;; これらの定義を完成させるには、RFC 9052から必要なCDDLを ;;; 挿入してください。これは手動で行うことも、次のような ;;; importディレクティブを実装するツールで自動化することも ;;; できます: ;# import rfc9052
